CREATE TABLE IF NOT EXISTS `site_profile` (`id` integer PRIMARY KEY NOT NULL, `about_heading_zh` text NOT NULL, `about_heading_en` text NOT NULL, `about_body_zh` text NOT NULL, `about_body_en` text NOT NULL, `skills_heading_zh` text NOT NULL, `skills_heading_en` text NOT NULL, `contact_heading_zh` text NOT NULL, `contact_heading_en` text NOT NULL, `contact_body_zh` text NOT NULL, `contact_body_en` text NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE IF NOT EXISTS `portfolio_projects` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `title_zh` text NOT NULL, `title_en` text NOT NULL, `description_zh` text NOT NULL, `description_en` text NOT NULL, `tag` text NOT NULL DEFAULT '', `link_url` text, `sort_order` integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS `portfolio_skills` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `name_zh` text NOT NULL, `name_en` text NOT NULL, `description_zh` text NOT NULL, `description_en` text NOT NULL, `sort_order` integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS `contact_links` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `label` text NOT NULL, `value` text NOT NULL, `link_url` text, `sort_order` integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS `site_content_meta` (`id` integer PRIMARY KEY NOT NULL, `seeded_at` integer NOT NULL);
